using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<Shipment>(entity =>
        {
            entity.HasIndex(s => s.TrackingNumber).IsUnique();
        });

        SeedData(builder);
    }

    private static void SeedData(ModelBuilder builder)
    {
        var now = DateTime.UtcNow;
        builder.Entity<Shipment>().HasData(
            new Shipment
            {
                Id = 1, TrackingNumber = "TRK-20260001",
                Origin = "New York, USA", Destination = "London, UK",
                Status = ShipmentStatus.InTransit,
                ShippedDate = now.AddDays(-3), EstimatedDelivery = now.AddDays(4),
                CustomerEmail = "alice@example.com", Description = "Electronics - 2 boxes"
            },
            new Shipment
            {
                Id = 2, TrackingNumber = "TRK-20260002",
                Origin = "Shanghai, China", Destination = "Los Angeles, USA",
                Status = ShipmentStatus.OutForDelivery,
                ShippedDate = now.AddDays(-10), EstimatedDelivery = now.AddDays(1),
                CustomerEmail = "bob@example.com", Description = "Furniture - 1 pallet"
            },
            new Shipment
            {
                Id = 3, TrackingNumber = "TRK-20260003",
                Origin = "Berlin, Germany", Destination = "Tokyo, Japan",
                Status = ShipmentStatus.Pending,
                ShippedDate = now, EstimatedDelivery = now.AddDays(7),
                CustomerEmail = "carol@example.com", Description = "Automotive parts"
            },
            new Shipment
            {
                Id = 4, TrackingNumber = "TRK-20260004",
                Origin = "São Paulo, Brazil", Destination = "Sydney, Australia",
                Status = ShipmentStatus.Delivered,
                ShippedDate = now.AddDays(-14), EstimatedDelivery = now.AddDays(-2),
                ActualDelivery = now.AddDays(-3),
                CustomerEmail = "dave@example.com", Description = "Textiles - 5 cartons"
            },
            new Shipment
            {
                Id = 5, TrackingNumber = "TRK-20260005",
                Origin = "Mumbai, India", Destination = "Dubai, UAE",
                Status = ShipmentStatus.Delayed,
                ShippedDate = now.AddDays(-5), EstimatedDelivery = now.AddDays(3),
                CustomerEmail = "eve@example.com", Description = "Machinery components"
            }
        );
    }
}

